$logPath = 'C:\Users\USER\.gemini\antigravity\brain\88563c89-6767-42ec-9a8c-38dfc1754c2c\.system_generated\logs\transcript_full.jsonl'
$lines = Get-Content $logPath
for ($i = 0; $i -lt $lines.Length; $i++) {
    $line = $lines[$i]
    if ($line.Contains('write_file') -and $line.Contains('pixel-renderer.js') -and $line.Contains('renderEnding4')) {
        Write-Host "Match at line $i"
        $json = ConvertFrom-Json $line
        if ($json.tool_calls) {
            foreach ($tc in $json.tool_calls) {
                if ($tc.name -eq 'write_file' -or $tc.function.name -eq 'write_file') {
                    $argsObj = if ($tc.arguments) { $tc.arguments } else { $tc.function.arguments }
                    if ($argsObj.Path -like '*pixel-renderer.js') {
                        Write-Host "Found write_file tool call in line $i with Content length: " $argsObj.Content.Length
                        [System.IO.File]::WriteAllText('C:\Users\USER\Desktop\juego\js\pixel-renderer.js', $argsObj.Content, [System.Text.Encoding]::UTF8)
                        Write-Host "Successfully restored pixel-renderer.js!"
                    }
                }
            }
        }
    }
}
